examples:
# Create a dictionary
set d [dict create name Alice age 30 city Boston]

# Get a value
dict get $d name  ;# Returns: Alice

# Check key existence
dict exists $d age  ;# Returns: 1

# Set a value in-place
dict set d country USA

# Get all keys
dict keys $d  ;# Returns: {name age city country}

# Increment a value
dict incr d age

# Iterate over key-value pairs
dict foreach {k v} $d {
  puts "$k = $v"
}

# Filter by key pattern
dict filter $d key a*  ;# Keys starting with 'a'

# Map: transform values
dict map {k v} {a 1 b 2 c 3} {
  expr {$v * 2}
}  ;# Returns: {a 2 b 4 c 6}

# Merge dictionaries (later wins)
dict merge {a 1 b 2} {b 3 c 4}  ;# Returns: {a 1 b 3 c 4}

# Remove keys (returns new dictionary)
dict remove {a b c d e f} c  ;# Returns: {a b e f}

# Update: map keys to local variables, modify, write back
set d [dict create x 1 y 2]
dict update d x a y b {
  set a [expr {$a + 10}]
}
dict get $d x  ;# Returns: 11

# With: unpack keys into local variables
set d [dict create a 1 b 2]
dict with d {
  set a [expr {$a + 10}]
  set b [expr {$b + 20}]
}
;# a=11, b=22

Simple procedure:


proc greet {name} {
    return "Hello, $name!"
}
puts [greet "World"]  ;# Hello, World!



Procedure with default argument:


proc greet {name {greeting "Hello"}} {
    return "$greeting, $name!"
}
puts [greet "World"]           ;# Hello, World!
puts [greet "World" "Hi"]      ;# Hi, World!



Variable arguments with args:


proc sum {args} {
    set total 0
    foreach num $args {
        incr total $num
    }
    return $total
}
puts [sum 1 2 3 4 5]  ;# 15



Mixed required, optional, and variable arguments:


proc format_list {prefix {separator ", "} args} {
    return "$prefix: [join $args $separator]"
}
puts [format_list "Items" "; " a b c]  ;# Items: a; b; c



Recursive procedure:


proc factorial {n} {
    if {$n 
<
= 1} {
        return 1
    }
    return [expr {$n * [factorial [expr {$n - 1}]]}]
}
puts [factorial 5]  ;# 120
